```latex
\section{Preliminaries}
\label{sec:prelims}

\subsection{Notation}

    \begin{itemize}
        \item Given a Markov chain $P$ on $\Omega$, and $x \in \Omega$, $P_x$ is the distribution over $\Omega$ obtained by taking one step of the Markov chain from $x$.
        \item Given $\sigma \in \{\pm 1\}^n$, $\sigma^{\oplus i} \in \{\pm 1\}^n$ is defined as
        \[ \left(\sigma^{\oplus i}\right)_j = \begin{cases} \sigma_j, & j \ne i, \\ -\sigma_i, & j = i. \end{cases} \]
        \item Given a matrix $M$, we denote its operator norm by $\|M\| = \|M\|_{\mathrm{op}}$.
        \item Given a distribution $\mu$ over $\Omega$ and a function $f : \Omega \to \R_{> 0}$,
        \[ \Ent[f] = \Ent_{\mu}[f] \defeq \E_{\mu}[f \log f] - \E_{\mu}[f] \log \E_{\mu}[f]. \]
        \item For a random variable $X$ over $\R^k$, we use $\Cov[X]$ to denote the covariance $\E[XX^\top] - \E[X]\E[X]^\top$. For a probability distribution $\mu$ over $\R^k$, we use $\Cov(\mu)$ to denote the covariance of the associated random variable with law $\mu$.
        \item Given a connected graph $G = (V,E)$, its \emph{tree-excess} is $|E|-|V|+1$.
        \item Given a graph $H$, we use $V(H)$ and $E(H)$ to denote its vertex and edge sets respectively. We use $V'(H)$ to refer to the subset of vertices of $V(H)$ adjacent to at least one other distinct vertex, the set of non-isolated vertices.
        \item For a matrix $M \in \R^{n \times n}$ and a set of vertices $S \subseteq [n]$, by $M_S$ we mean the $n \times n$ matrix where every row and column outside $S$ is zeroed out, i.e., the principal submatrix of $M$ restricted to $S$ but preserving the dimension. If $H$ is a graph on $[n]$, then by $M_H \in \R^{n \times n}$ we mean $M_{V'(H)}$, i.e., the restriction of $M$ to the non-isolated vertices of $H$.
        \item We often abuse notation and identify probability measures $\mu$ with their density functions.
    \end{itemize}

\subsection{Markov chains}

    \begin{definition}[Glauber dynamics]
        Let $\Omega = \{\pm 1\}^n$, and suppose that $\mu$ is supported on all of $\Omega$. The corresponding \emph{Glauber dynamics} Markov chain $P = P_\mu$ is described by the following transition law from any state $\sigma$:
        \begin{itemize}
            \item Choose index $i$ uniformly at random from $[n]$.
            \item Go to $\sigma^{\oplus i}$ with probability $\displaystyle\frac{\mu(\sigma^{\oplus i})}{\mu(\sigma)+\mu(\sigma^{\oplus i})}$, and stay at $\sigma$ otherwise.
        \end{itemize}
    \end{definition}

    \begin{definition}[Dirichlet Form]
        Given a distribution $\mu$ over $\{\pm 1\}^n$, a time-reversible Markov chain $P$ with stationary distribution $\mu$, and functions $f,g : \{\pm 1\}^n \to \R$, the associated \emph{Dirichlet form} is defined as
        \[ \mathcal{E}(f,g) = \mathcal{E}_{P}(f,g) \defeq \underset{\substack{x \sim \mu \\ y \sim P_x}}{\E} \left[ (f(x) - f(y))(g(x) - g(y)) \right]. \]
    \end{definition}

    \begin{definition}[Modified log-Sobolev Inequality]
        Given a time-reversible Markov chain $P$ on $\{\pm 1\}^n$ with stationary distribution $\mu$, $P$ is said to satisfy a \emph{modified log-Sobolev inequality} (MLSI) with constant $C$ (possibly depending on $n$) if for any function $f : \{\pm 1\}^n \to \R_{> 0}$,
        \[ \mathcal{E}(f,\log f) \ge C \Ent[f]. \]
        In particular, $\MLSI$ is the best (largest) such constant $C$.
    \end{definition}

    \begin{fact}[{\cite[Lemma 2.5]{Goe04}}]
        \label{fact:mlsi-product}
        Let $\mu$ be a distribution on $\{\pm 1\}^n$, and $(C_i)_{i=1}^{k}$ a partition of $[n]$ such that there exist distributions $\mu^{(i)}$ on $\{\pm 1\}^{C_i}$ with $\mu = \bigotimes_{i=1}^{K} \mu^{(i)}$. For the Glauber dynamics Markov chain, if each $\mu^{(i)}$ satisfies an MLSI with constant $\rho^{(i)}$, then $\mu$ satisfies an MLSI with constant $\rho = \frac{1}{n} \min_{i} \rho^{(i)} |C_i|$. 
    \end{fact}

    \begin{lemma}[{\cite[p. 1186]{HS86}, see also \cite[Lemma 1.2]{Led01}}]\label{lem:mlsi-bdd-density-relate}
      Let $\mu,\nu$ be two probability measures over $\{\pm1\}^{n}$, and suppose that for some $c > 1$ (possibly depending on $n$), $\frac{1}{c} \leq \frac{\nu(\sigma)}{\mu(\sigma)} \leq c$ uniformly over all $\sigma \in \{\pm1\}^{n}$.
      \begin{enumerate}
          \item Suppose Glauber dynamics for $\mu$ has MLSI constant at least $\MLSI$. Then, Glauber dynamics for $\nu$ has MLSI constant at least $\MLSI / c^2$.
          \item For any function $f$,
          \[ \frac{1}{c} \cdot \Var_{\mu}[f] \le \Var_{\nu}[f] \le c \cdot \Var_{\mu}[f]. \]
      \end{enumerate}
      Also note that if $\nu \propto e^{-f}$ and $\mu \propto e^{-g}$, and $\|f-g\|_{\infty} \le \wt{c}$, then $e^{-2\wt{c}} \le \frac{\nu(\sigma)}{\mu(\sigma)} \le e^{2\wt{c}}$.
    \end{lemma}

\subsection{Ising models}
    \begin{definition}[Ising model]
        The \emph{Ising model} corresponding to $J$ and $h$ is the probability distribution $\mu_{J, h}$ on $\{\pm1\}^n$, where
        \[
            \mu_{J, h}(\sigma) \propto \exp\parens*{\frac{1}{2}\sigma^\top J \sigma + \langle h,\sigma\rangle}.
        \]
        Its \emph{partition function} is
        \[
            Z_{J, h} \coloneqq \sum_{\sigma\in\{\pm1\}^n} \exp\parens*{\frac{1}{2}\sigma^{\top} J\sigma + \angles*{h,\sigma}}.    
        \]
    \end{definition}

\subsection{Localization schemes}   \label{sec:loc-schemes}

    \begin{definition}[Stochastic localization for Ising models]    \label{def:stoc-loc}
        A \emph{stochastic localization scheme} is a stochastic process $\parens*{\mu_{t}}_{0\le t\le 1}$ on the space of Ising models that is parameterized by a (possibly time-varying) \emph{control matrix} $(C_t)_{0 \le t \le 1}$ and an \emph{initialization} $\mu_{J,h}$, described by the following stochastic differential equation.
        \begin{equation}
            \dif\parens*{\frac{\mu_{t}}{\mu_{J,h}}} = \frac{\mu_{t}}{\mu_{J,h}} \angles*{ x-\E_{\mu_{t}} x, C_t \cdot \dif B_t } \label{eq:stoc-loc}
        \end{equation}
        where $(B_t)_{0\le t\le 1}$ is the standard Brownian motion in $n$ dimensions.
    \end{definition}

    \begin{fact}[{\cite[Facts 13 and 14]{CE22}}]    \label{fact:stoc-loc-form}
        The distribution $\mu_t$ is the Ising model
        \(
            \mu_{J_t, h_t}
        \)
        where $J_t = J - \int_{0}^{t} C_s^2 \dif s$ and $h_t = \int_0^t C_s \cdot \dif B_s + C_s^2 \E_{\mu_s} [x] \cdot \dif s$.
        Further, $\mu_t$ is a martingale, in that for any set $A \subseteq \{\pm 1\}^n$, $\E[\mu_t(A)|\mu_s] = \mu_s(A)$ for $0\le s\le t\le 1$.
    \end{fact}

    \begin{lemma}   \label{lem:entropic-stability}
        Consider a stochastic localization process $(\mu_t)_{t \ge 0}$ with respect to (possibly time-varying) control matrix $(C_t)_{t \ge 0}$, started at an Ising model $\mu_0 = \mu_{J,h}$. Suppose that for every $h'\in\R^n$ and $t \in [0,1]$,
        \[
            \norm*{C_t \cdot \Cov\parens*{\mu_{J_t, h'}} \cdot C_t} \le \alpha_t.
        \]
        Then, for any positive-valued $\varphi$,
        \[
            \E \left[\Ent_{\mu_{1}}[\varphi]\right] \ge \exp\parens*{-\int_{0}^{1} \alpha_t \dif t} \cdot \Ent_{\mu_{J,h}}[\varphi].
        \]
    \end{lemma}

    \begin{theorem}[{\cite[Theorem 47]{CE22}}]  \label{thm:anneal}
        Let $J$ be an interaction matrix and $h$ be an external field.
        Let $(\mu_t)_{0\le t\le 1}$ be a stochastic localization scheme initialized at $\mu_{J,h}$.
        Suppose that
        \begin{enumerate}
            \item \label{item:entropy-conservation} We have the entropy conservation inequality
            \[ \frac{\E[\Ent_{\mu_1}[f]]}{\Ent_{\mu_{J,h}}[f]} \ge \eps \]
            for all $f : \Omega \to \R_+$.
            \item \label{item:MLSI-target} Almost surely,
            \[ \MLSI(P_{\mu_1}) \ge \delta. \]
        \end{enumerate}
        Then, $\mu_{J,h}$ has an MLSI coefficient at least $\eps\delta$.
    \end{theorem}

\subsection{Graphs} \label{sec:graph-prelims}

    For the rest of this section, let $G$ be a graph on $n$ vertices and $m$ edges, and let $c$ be a weight function on this graph.
    We will use $A_c$ to denote the adjacency matrix of $G$, weighted according to $c$, and $D_c$ as the weighted degree function where $D_c[i,i] = \sum_{j\ne i} A_c[i,j]$.

    \begin{definition}[Bethe Hessian]
        \label{def:bethe-hessian}
        The \emph{Bethe Hessian} is defined as:
        \(
            \BH_{c} \coloneqq D_{c\wh{c}} - A_{\wh{c}} + I
        \)
        where $\wh{c} = \frac{c}{1-c^2}$.
        When all the weights are equal to $t$, the Bethe Hessian can be written as:
        \[
            \BH_G(t) \coloneqq \frac{(D_G-I)t^2 - At + I}{1-t^2}.
        \]
    \end{definition}

    \begin{corollary}
        \label{cor:bethe-tree-psd}
        When $G$ is a tree, for all $t\in(-1,1)$, we have $\BH_G(t)\psdg 0$.
    \end{corollary}

    We define $A_G^{(s)}$ as the $n\times n$ matrix where the $i,j$ entry contains the number of length-$s$ nonbacktracking walks between $i$ and $j$.

    \begin{fact}
        \label{fact:bethe-inverse}
        $\displaystyle \BH_G(t)^{-1} = \sum_{s\ge 0} A_G^{(s)}t^s$.
    \end{fact}

\section{Glauber dynamics on near-forest decompositions}
\label{sec:spinglass}

\subsection{On decomposing random graphs}
\label{sec:decomposition}

    \begin{definition}[Near-forest]
        We say a graph $H$ is a \emph{near-forest} if all its connected components have at most a single cycle. Equivalently, each component has tree-excess at most $1$.
    \end{definition}

    \begin{definition}[Pseudorandom graph]\label{def:pseudorandom-graph}
        We say a graph $H$ is \emph{$(\Delta,D)$-pseudorandom} with respect to $S \subseteq V(H)$ if it satisfies the following:
        \begin{enumerate}
            \item For any $r\ge 1$, and any vertex $u\in V(H)$, the size of the $r$-ball around $u$ is at most $D^{r-1}\cdot\Delta$. Note in particular that this implies that the maximum degree is at most $\Delta$.
            \item For any $r\ge 0$ and $u\in V(H)$, $\abs*{\braces*{v\in S: \dist(u,v)\le r}} \le D^r$. 
        \end{enumerate}
    \end{definition}

\subsection{Covariance bounds on near-forests}\label{sec:covariance-near-forest}

    \begin{observation} \label{obs:sign-conjugation}
        For any interaction matrix $J$, external field $h$, and diagonal matrix of signs $D$, we have:
        \[
            \norm*{\Cov\parens*{\mu_{J,h}}} = \norm*{\Cov\parens*{\mu_{DJD, Dh}}}\mper
        \]
        In fact, $\MLSI(\mu_{J,h}) = \MLSI(\mu_{DJD,Dh})$.
    \end{observation}

    \begin{lemma}   \label{lem:all-but-one-neg}
        For any connected graph $H$ and spanning tree $T$ of $H$, interaction matrix $J$ supported on $H$, and an external field $h$, there is a diagonal matrix $D$ such that $DJD$ has nonnegative interactions on the edges of $T$.
    \end{lemma}

    \begin{corollary}
        \label{cor:cov-ferro-external-psd}
        Let $M$ be a matrix with all non-negative entries. For any ferromagnetic interaction matrix $J\in\R_{\ge 0}^{n\times n}$ and external field $h\in\R^n$, we have
        \[
            \left\|\Cov\parens*{\mu_{J,h}} \cdot M\right\| \le \left\|\Cov\parens*{\mu_{J,0}} \cdot M\right\|.
        \]
        In particular,
        \[ \left\|\Cov(\mu_{J,h})\right\| \le \left\|\Cov(\mu_{J,0})\right\|. \]
    \end{corollary}

    \begin{lemma} \label{lem:tree-cov}
        Let $H$ be a $(\Delta,D)$-pseudorandom tree with respect to $S\subseteq V(H)$. Let $A$ be the adjacency matrix of $H$.
        If $J$ is a collection of interactions supported on the edges of $H$ with values in $\bracks*{0, \frac{\gamma}{\sqrt{D}}}$ for some $\gamma \in [0,1)$, then
        \begin{align*}
            \norm*{\Cov\parens*{\mu_{J,0}}_S} &\le \frac{1}{(1-\gamma)^2} \\
            \norm*{\Cov\parens*{\mu_{J,0}}} &\le \frac{1}{(1-\gamma)^2}\cdot\frac{\Delta}{D} \\
            \norm*{\Cov\left(\mu_{J,0}\right) \cdot A} &\le \frac{1}{(1-\gamma)^2} \cdot \frac{2\Delta}{\sqrt{D}} \mper
        \end{align*}
    \end{lemma}

\subsection{MLSI for Ising models on pseudorandom near-forests}
\label{sec:mlsi-tree-ising}
